import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom"; // Updated import for v6

import Modal from "react-modal"; // Assuming you're using react-modal for the warning modal

const SearchFood = () => {
  const [query, setQuery] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [warningModalOpen, setWarningModalOpen] = useState(false);
  const [selectedFood, setSelectedFood] = useState(null);
  const navigate = useNavigate(); // Use navigate instead of history

  // Check if user is logged in
  const isAuthenticated = localStorage.getItem("token"); // Assuming you store the token in localStorage

  const handleSearch = async () => {
    if (!isAuthenticated) {
      setWarningModalOpen(true);
      return;
    }

    try {
      const response = await axios.get(
        `http://localhost:8000/api/search/?query=${query}`
      );
      setSearchResults(response.data);
    } catch (error) {
      console.error("Error fetching food data", error);
    }
  };

  const handleSelectFood = (food, mealType) => {
    setSelectedFood({ ...food, mealType });
    // Send POST request to store the selected food data
    saveFoodToDatabase(food, mealType);
  };

  const saveFoodToDatabase = async (food, mealType) => {
    if (!isAuthenticated) {
      setWarningModalOpen(true);
      return;
    }

    try {
      await axios.post(
        "http://localhost:8000/api/save_food/",
        {
          food_id: food.fdcId,
          meal_type: mealType,
          food_name: food.description,
          ingredients: food.ingredients,
          nutrients: food.nutrients,
          user: localStorage.getItem("userId"), // Assuming userId is saved in localStorage
          date: new Date().toISOString(),
        },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );

      alert("Food saved successfully!");
    } catch (error) {
      console.error("Error saving food data", error);
    }
  };

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search food..."
      />
      <button onClick={handleSearch}>Search</button>

      <div>
        {searchResults.map((food) => (
          <div key={food.fdcId}>
            <h3>{food.description}</h3>
            <p>Ingredients: {food.ingredients}</p>
            <p>Nutrients: {food.nutrients}</p>

            {/* Dropdown for selecting meal type */}
            <select
              onChange={(e) => handleSelectFood(food, e.target.value)}
              value={selectedFood?.mealType || ""}
            >
              <option value="">Select Meal</option>
              <option value="breakfast">Breakfast</option>
              <option value="lunch">Lunch</option>
              <option value="dinner">Dinner</option>
            </select>
          </div>
        ))}
      </div>

      {/* Warning Modal */}
      <Modal
        isOpen={warningModalOpen}
        onRequestClose={() => setWarningModalOpen(false)}
      >
        <h2>Login first to search and record your nutrition data</h2>
        <button onClick={() => navigate("/auth")}>Go to Login</button>{" "}
        {/* Updated to use navigate */}
        <button onClick={() => setWarningModalOpen(false)}>Close</button>
      </Modal>
    </div>
  );
};

export default SearchFood;
